import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.mzJ8I8R4.js";const _=JSON.parse('{"title":"AI 整理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai.md","filePath":"guide/ai.md"}'),i={name:"guide/ai.md"};function d(o,t,p,h,n,s){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-整理" tabindex="-1">AI 整理 <a class="header-anchor" href="#ai-整理" aria-label="Permalink to &quot;AI 整理&quot;">​</a></h1><p>把随手写下的一大段话交给 AI，整理成一条或几条事项：标题、描述、截止时间和先后关系都会填好，原文的信息不丢。也可以让 AI 整理一个文件夹里已有的事项。</p><p>NextTodo 不提供 AI，用的是自己在大模型服务商那里申请的 API 密钥，费用由服务商按用量收取。</p><h2 id="key" tabindex="-1">1. 获取 API 密钥 <a class="header-anchor" href="#key" aria-label="Permalink to &quot;1. 获取 API 密钥 {#key}&quot;">​</a></h2><p>API 密钥是一串字符（通常以 <code>sk-</code> 开头），是在服务商那里使用模型的凭证，不要告诉别人。任选一家服务商：</p><table tabindex="0"><thead><tr><th>服务商</th><th>控制台</th><th>说明</th></tr></thead><tbody><tr><td>DeepSeek</td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a></td><td>国内可直接使用</td></tr><tr><td>通义千问</td><td><a href="https://bailian.console.aliyun.com" target="_blank" rel="noreferrer">阿里云百炼</a></td><td>国内可直接使用</td></tr><tr><td>OpenAI</td><td><a href="https://platform.openai.com" target="_blank" rel="noreferrer">platform.openai.com</a></td><td>需要境外的支付方式</td></tr></tbody></table><p>步骤大致相同：</p><ol><li>注册并登录服务商的控制台，按要求完成实名认证或充值。</li><li>在控制台的“API Key”页面创建一个密钥。</li><li>立即复制并妥善保存：多数服务商只在创建时显示一次完整的密钥。</li></ol><p>也可以用其他兼容 OpenAI 接口的服务商，选择“自定义”，填写它的接口地址和模型名称。</p><h2 id="_2-在-nexttodo-里配置" tabindex="-1">2. 在 NextTodo 里配置 <a class="header-anchor" href="#_2-在-nexttodo-里配置" aria-label="Permalink to &quot;2. 在 NextTodo 里配置&quot;">​</a></h2><ol><li>打开“设置 → AI 整理”，点“模型”。</li><li>选择服务商，接口地址和模型会自动填好。</li><li>把 API 密钥粘贴到“API 密钥”一栏。</li><li>点“测试”，显示成功就说明配置正确；失败时会显示服务商返回的原因，比如密钥错误或余额不足。</li><li>点“保存”。</li></ol><p>在本机使用时，配置只保存在这台设备上，没有其他选项。连接服务器时，保存前还要选择“保存位置”：</p><table tabindex="0"><thead><tr><th>保存位置</th><th>密钥存在</th><th>什么时候整理</th></tr></thead><tbody><tr><td>仅本机</td><td>这台设备上</td><td>这台设备联网时</td></tr><tr><td>同步到服务器</td><td>服务器上，加密保存</td><td>提交后设备可以离线，服务器自己整理</td></tr></tbody></table><p>选“同步到服务器”需要服务器设置过加密密钥，见<a href="./server#ai">部署服务器</a>。</p><p>“思考程度”越高，整理得越仔细，也越慢、费用越高。</p><h2 id="_3-把一段话整理成事项" tabindex="-1">3. 把一段话整理成事项 <a class="header-anchor" href="#_3-把一段话整理成事项" aria-label="Permalink to &quot;3. 把一段话整理成事项&quot;">​</a></h2><ol><li>点添加框里的 ✦，切换到 AI 整理。</li><li>写下要做的事，想到什么写什么，可以很长。这时回车是换行。</li><li>点发送按钮提交；电脑上也可以按 Ctrl + Enter（macOS 上 ⌘ + Enter）。</li></ol><p>提交后不用等：列表顶部出现一行“整理中”，整理好后变成事项，提示条写着添加了几项。不满意可以点“撤销”，原文还在，可以改了再试。</p><p>整理失败时，那一行会写明原因。点开它可以重试、修改原文后重试，或者“按原文添加”成一个事项。</p><p>发给服务商的内容：原文、提交时间、所在文件夹的路径，以及这个文件夹里未完成事项的编号、标题、截止时间和先后关系（最多 50 项），好让 AI 把新事项接在已有事项后面。已有事项的描述不发。</p><h2 id="_4-整理已有的事项" tabindex="-1">4. 整理已有的事项 <a class="header-anchor" href="#_4-整理已有的事项" aria-label="Permalink to &quot;4. 整理已有的事项&quot;">​</a></h2><p>文件夹里的事项写得乱、漏了先后关系时，可以让 AI 整理一遍。AI 只提出建议，确认后才会修改。</p><ol><li>点文件夹页顶部的“…”按钮（电脑上也可以右键文件夹），选“AI 整理事项”。</li><li>写下要求，或者直接用默认的“把标题改清楚，描述改成简洁的书面语，补上漏掉的先后关系。”，提交。</li><li>整理好后，列表顶部显示“N 条建议，待确认”。点开它： <ul><li>每个事项先写着 AI 的理由，下面每处修改一个勾选框：新标题和描述、截止时间、要加的前置。</li><li>取消勾选不想要的修改，点“应用 N 处”。应用后可以撤销。</li><li>不想要这批建议，点“放弃”；想按现在的事项重来，点“重新整理”。</li></ul></li></ol><p>整理时会把这个文件夹里未完成事项的标题、描述、截止时间和先后关系发给服务商。</p>',24)])])}const A=e(i,[["render",d]]);export{_ as __pageData,A as default};
